// `next` is referenced by its own initializer's inference (through
// `chunk = next`), so the checker types it `any` while it is a Uint8Array.
export function grow(parts) {
  let chunk;
  for (const value of parts) {
    if (!chunk) chunk = value.slice(0);
    else {
      const next = new Uint8Array(new ArrayBuffer(Math.max(8, chunk.byteLength * 2)));
      next.set(chunk.subarray(0, 2));
      next.set([9], 2);
      next[3] = next.byteLength;
      console.log(next.length, next[0], next.subarray(1, 3), next.at(-1), next.byteOffset);
      console.log(next.slice(2, 4), next.buffer.byteLength, next.BYTES_PER_ELEMENT);
      chunk = next;
    }
  }
  return chunk;
}
